-- -----------------------------------------------------------------------------
-- Row Level Security: enable on all platform tables
-- -----------------------------------------------------------------------------

do $$
declare
  t text;
begin
  foreach t in array array[
    'profiles', 'user_settings', 'user_security_events', 'workspaces', 'workspace_roles',
    'workspace_members', 'workspace_invites', 'workspace_settings', 'notification_preferences',
    'connected_accounts', 'projects', 'project_members', 'chats', 'chat_branches',
    'chat_messages', 'chat_message_parts', 'chat_message_reactions', 'pinned_chats',
    'library_items', 'saved_prompts', 'artifacts', 'artifact_versions', 'user_files',
    'file_versions', 'file_processing_jobs', 'model_catalog', 'model_usage_events',
    'tool_calls', 'research_runs', 'research_sources', 'document_chunks', 'embeddings',
    'plans', 'subscriptions', 'billing_orders', 'billing_payments', 'token_transactions',
    'user_balances', 'rate_limits', 'webhook_events', 'audit_logs', 'api_keys',
    'abuse_reports', 'feature_flags'
  ] loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- updated_at triggers (tables with updated_at column)
-- -----------------------------------------------------------------------------

do $$
declare
  r record;
begin
  for r in
    select table_name
    from information_schema.columns
    where table_schema = 'public'
      and column_name = 'updated_at'
      and table_name in (
        'profiles', 'workspaces', 'workspace_roles', 'workspace_settings',
        'notification_preferences', 'connected_accounts', 'projects', 'chats',
        'chat_messages', 'library_items', 'saved_prompts', 'artifacts',
        'user_files', 'file_processing_jobs', 'model_catalog', 'plans',
        'subscriptions', 'abuse_reports', 'feature_flags'
      )
  loop
    select public.ensure_updated_at_trigger(format('public.%I', r.table_name)::regclass);
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- RLS policies
-- -----------------------------------------------------------------------------
-- Patterns:
--   - "own_*"     → auth.uid() matches user_id / id
--   - workspace   → owner_id or active workspace_members row
--   - read-only   → model_catalog, plans, feature_flags (enabled only)
-- -----------------------------------------------------------------------------

-- --- Profiles & workspaces ---

drop policy if exists "profiles_manage_own" on public.profiles;

create policy "profiles_manage_own" on public.profiles
for all to authenticated
using (auth.uid() = id)
with check (auth.uid() = id);

drop policy if exists "workspaces_read_member" on public.workspaces;

create policy "workspaces_read_member" on public.workspaces
for select to authenticated
using (owner_id = auth.uid() or exists (
  select 1 from public.workspace_members wm
  where wm.workspace_id = workspaces.id and wm.user_id = auth.uid() and wm.status = 'active'
));

drop policy if exists "workspaces_owner_write" on public.workspaces;

create policy "workspaces_owner_write" on public.workspaces
for all to authenticated
using (owner_id = auth.uid())
with check (owner_id = auth.uid());

-- --- Workspace members & invites ---

drop policy if exists "workspace_members_read_member" on public.workspace_members;

create policy "workspace_members_read_member" on public.workspace_members
for select to authenticated
using (user_id = auth.uid() or exists (
  select 1 from public.workspaces w where w.id = workspace_members.workspace_id and w.owner_id = auth.uid()
));

drop policy if exists "workspace_members_owner_write" on public.workspace_members;

create policy "workspace_members_owner_write" on public.workspace_members
for all to authenticated
using (exists (select 1 from public.workspaces w where w.id = workspace_members.workspace_id and w.owner_id = auth.uid()))
with check (exists (select 1 from public.workspaces w where w.id = workspace_members.workspace_id and w.owner_id = auth.uid()));

drop policy if exists "workspace_invites_owner_write" on public.workspace_invites;

create policy "workspace_invites_owner_write" on public.workspace_invites
for all to authenticated
using (exists (select 1 from public.workspaces w where w.id = workspace_invites.workspace_id and w.owner_id = auth.uid()))
with check (exists (select 1 from public.workspaces w where w.id = workspace_invites.workspace_id and w.owner_id = auth.uid()));

drop policy if exists "workspace_scoped_read" on public.workspace_settings;

create policy "workspace_scoped_read" on public.workspace_settings
for select to authenticated
using (exists (
  select 1 from public.workspace_members wm
  where wm.workspace_id = workspace_settings.workspace_id and wm.user_id = auth.uid() and wm.status = 'active'
) or exists (select 1 from public.workspaces w where w.id = workspace_settings.workspace_id and w.owner_id = auth.uid()));

drop policy if exists "workspace_settings_owner_write" on public.workspace_settings;

create policy "workspace_settings_owner_write" on public.workspace_settings
for all to authenticated
using (exists (select 1 from public.workspaces w where w.id = workspace_settings.workspace_id and w.owner_id = auth.uid()))
with check (exists (select 1 from public.workspaces w where w.id = workspace_settings.workspace_id and w.owner_id = auth.uid()));

